using OperationsRequests.Domain;namespace OperationsRequests.Services;
public sealed class ScopeService{public bool CanView(TrainingRequest r,ApplicationUser u,IList<string> roles)=>roles.Contains(Roles.PlatformAdmin)||(roles.Contains(Roles.CountryOpsManager)&&u.CountryId==r.Site.Territory.CountryId)||(roles.Contains(Roles.TerritoryManager)&&u.TerritoryId==r.Site.TerritoryId)||(roles.Contains(Roles.SiteManager)&&u.SiteId==r.SiteId)||r.RequestedById==u.Id;public bool CanCreateAt(Site s,ApplicationUser u,IList<string> roles)=>roles.Contains(Roles.PlatformAdmin)||(roles.Contains(Roles.CountryOpsManager)&&u.CountryId==s.Territory.CountryId)||(roles.Contains(Roles.TerritoryManager)&&u.TerritoryId==s.TerritoryId)||(roles.Contains(Roles.SiteManager)&&u.SiteId==s.Id)||(roles.Contains(Roles.StaffMember)&&u.SiteId==s.Id);}
